"""Backup VLM: vlm.backup_url in the settings; a failed request is retried on the backup at once, the client stays
there 60 s, then tries the main one again. One VLM watch per server (vlm_down names the server).
Run from ~/vision-pipeline. Each change must match exactly once; prints patched / already done."""
import pathlib

EDITS = {'vp/vlm.py': [('ask() returns a Future at once; at most max_in_flight requests run together; replies are parsed robustly."""\n', 'ask() returns a Future at once; at most max_in_flight requests run together; replies are parsed robustly.\nWith a backup_url: a failed request is retried on the backup at once, and the client stays on the backup for\nretry_primary_s before trying the primary again. Each result says which server answered."""\n'), ('    def __init__(self, url, model, timeout_s=30.0, max_in_flight=1):\n        self.url = url.rstrip("/") + "/chat/completions"\n', '    def __init__(self, url, model, timeout_s=30.0, max_in_flight=1, backup_url=None, retry_primary_s=60.0):\n        self.urls = [u.rstrip("/") + "/chat/completions" for u in (url, backup_url) if u]\n        self.url = self.urls[0]\n        self.retry_primary_s, self._primary_failed_at = retry_primary_s, None\n'), ('\n    def _call(self, images_rgb, prompt, max_tokens):\n', '\n    def _order(self):\n        """Primary first, unless it failed less than retry_primary_s ago: then the backup first."""\n        with self._lock:\n            recent = self._primary_failed_at is not None and time.time() - self._primary_failed_at < self.retry_primary_s\n        return self.urls[1:] + self.urls[:1] if recent and len(self.urls) > 1 else list(self.urls)\n\n    def _call(self, images_rgb, prompt, max_tokens):\n'), ('        req = urllib.request.Request(self.url, data=body, headers={"Content-Type": "application/json"})\n        t0 = time.time()\n        with urllib.request.urlopen(req, timeout=self.timeout) as r:\n            reply = json.loads(r.read())["choices"][0]["message"]["content"]\n        return {"answer": parse_json(reply), "raw": reply, "seconds": round(time.time() - t0, 2)}\n', '        t0, error = time.time(), None\n        for url in self._order():\n            try:\n                req = urllib.request.Request(url, data=body, headers={"Content-Type": "application/json"})\n                with urllib.request.urlopen(req, timeout=self.timeout) as r:\n                    reply = json.loads(r.read())["choices"][0]["message"]["content"]\n            except Exception as e:  # this server failed: note it, try the next one\n                error = e\n                if url == self.urls[0]:\n                    with self._lock:\n                        self._primary_failed_at = time.time()\n                continue\n            if url == self.urls[0]:\n                with self._lock:\n                    self._primary_failed_at = None\n            return {"answer": parse_json(reply), "raw": reply, "seconds": round(time.time() - t0, 2),\n                    "server": "primary" if url == self.urls[0] else "backup"}\n        raise error\n')], 'vp/vlm_watch.py': [('import urllib.request\n\n', 'import urllib.request\nfrom urllib.parse import urlsplit\n\n'), ('        self.url = url.rstrip("/") + "/models"\n        self.outbox, self.every, self.fails_to_alert, self.timeout = outbox, every_s, fails_to_alert, timeout_s\n', '        self.url = url.rstrip("/") + "/models"\n        self.server = urlsplit(url).netloc  # host:port, names the VLM server in alerts\n        self.outbox, self.every, self.fails_to_alert, self.timeout = outbox, every_s, fails_to_alert, timeout_s\n'), ('                events.append(self._event("vlm_up", "info", now, self.down_since, down_for_s=round(now - self.down_since)))\n', '                events.append(self._event("vlm_up", "info", now, self.down_since, server=self.server,\n                                          down_for_s=round(now - self.down_since)))\n'), ('                events.append(self._event("vlm_down", "warning", now, now, url=self.url, failed_checks=self.fails))\n', '                events.append(self._event("vlm_down", "warning", now, now, server=self.server, url=self.url,\n                                          failed_checks=self.fails))\n'), ('    @staticmethod\n    def _event(cls, severity, ts, since, **extra):\n', '    def _event(self, cls, severity, ts, since, **extra):\n'), ('                "incident": f"vlm:down:{int(since)}", "confidence": 1.0, "track_id": None, "extra": extra}\n', '                "incident": f"vlm:{self.server}:down:{int(since)}", "confidence": 1.0, "track_id": None, "extra": extra}\n')], 'vp/main.py': [('        VLMWatch(settings.vlm["url"], outbox).start()  # one vlm_down alert for the node, not one per camera\n', '        for url in (settings.vlm["url"], settings.vlm.get("backup_url")):  # one watch per VLM server\n            if url:\n                VLMWatch(url, outbox).start()  # one vlm_down alert per server, not one per camera\n')], 'vp/plugins/fire_smoke.py': [('                                v.get("timeout_s", 30.0), max_in_flight=1)\n', '                                v.get("timeout_s", 30.0), max_in_flight=1, backup_url=v.get("backup_url"))\n')], 'vp/plugins/worker_at_height.py': [('                                v.get("timeout_s", 30.0), max_in_flight=g("max_in_flight", 2))\n', '                                v.get("timeout_s", 30.0), max_in_flight=g("max_in_flight", 2), backup_url=v.get("backup_url"))\n')], 'tests/test_vlm_watch.py': [('    assert box.events[0]["incident"] == box.events[1]["incident"] == "vlm:down:60", "down and up must share one incident"\n', '    assert box.events[0]["incident"] == box.events[1]["incident"] == f"vlm:127.0.0.1:{vlm.port}:down:60", \\\n        "down and up must share one incident, named after the server"\n')]}
NEW_FILES = {'tests/test_vlm_failover.py': '"""VLM client with a backup: main server off and on again. Run: python3 -m tests.test_vlm_failover"""\nimport http.server, json, threading, time\n\nimport numpy as np\n\nfrom vp.vlm import VLMClient\n\n\nclass PretendVLM:\n    """Answers chat/completions with its own name, counts requests, and can stop and start on the same port."""\n    def __init__(self, name, port=0):\n        self.name, self.hits = name, 0\n        outer = self\n\n        class H(http.server.BaseHTTPRequestHandler):\n            def do_POST(self):\n                self.rfile.read(int(self.headers["Content-Length"]))\n                outer.hits += 1\n                body = json.dumps({"choices": [{"message": {"content": json.dumps({"from": outer.name})}}]}).encode()\n                self.send_response(200); self.end_headers(); self.wfile.write(body)\n\n            def log_message(self, *a):\n                pass\n        self.httpd = http.server.HTTPServer(("127.0.0.1", port), H)\n        self.port = self.httpd.server_address[1]\n        threading.Thread(target=self.httpd.serve_forever, daemon=True).start()\n\n    def stop(self):\n        self.httpd.shutdown(); self.httpd.server_close()\n\n\ndef run():\n    main, backup = PretendVLM("main"), PretendVLM("backup")\n    c = VLMClient(f"http://127.0.0.1:{main.port}/v1", "m", timeout_s=2, backup_url=f"http://127.0.0.1:{backup.port}/v1",\n                  retry_primary_s=1.0)\n    img = np.zeros((8, 8, 3), np.uint8)\n    ask = lambda: c.ask([img], "q").result()\n    r = ask(); print("both up      ->", r["server"], r["answer"]); assert r["server"] == "primary"\n    main_port = main.port; main.stop()\n    r = ask(); print("main off     ->", r["server"], r["answer"]); assert r["server"] == "backup", "retried on the backup at once"\n    hits = backup.hits\n    r = ask(); print("still off    ->", r["server"], "(straight to the backup)"); assert r["server"] == "backup"\n    assert backup.hits == hits + 1\n    main = PretendVLM("main", main_port)\n    r = ask(); print("main back    ->", r["server"], "(still within 1 s: stays on backup)"); assert r["server"] == "backup"\n    time.sleep(1.1)\n    r = ask(); print("after 1 s    ->", r["server"], r["answer"]); assert r["server"] == "primary", "tries the main one again"\n    backup.stop(); main.stop()\n    try:\n        VLMClient(f"http://127.0.0.1:{main_port}/v1", "m", timeout_s=1, backup_url=f"http://127.0.0.1:{backup.port}/v1").ask([img], "q").result()\n        raise AssertionError("both down must raise")\n    except AssertionError:\n        raise\n    except Exception as e:\n        print("both off     -> error:", type(e).__name__)\n    print("PASS: backup answers when the main VLM is down, sticks to it, returns to the main one, errors only when both are down")\n\n\nif __name__ == "__main__":\n    run()\n'}

for path, text in NEW_FILES.items():
    p = pathlib.Path(path)
    if p.exists() and p.read_text() == text:
        print(f"{path}: already done")
    else:
        p.write_text(text); print(f"{path}: created")
for path, pairs in EDITS.items():
    p = pathlib.Path(path); t = p.read_text()
    if all(t.count(new) == 1 for old, new in pairs):
        print(f"{path}: already done"); continue
    for old, new in pairs:
        if t.count(old) != 1:
            raise SystemExit(f"{path}: expected exactly one match, found {t.count(old)}; stopping")
        t = t.replace(old, new)
    p.write_text(t); print(f"{path}: patched")
